def emit(nodes: dict, edges: list, res: dict, tx: int = 1) -> str:
    L = []
    L.append(";; asobi 遊び — GENERATED kotoba Datom log (ADR-2606073200). DO NOT hand-edit.")
    L.append(";; Canonical EAVT state (ADR-2605312345). [e a v tx op].")
    L.append(";; GROUND op :add = durable. DERIVED :bond/is-transient = computed on read (N1/G2).")
    L.append("[")

    for nid in nodes:
        n = nodes[nid]
        for a in NODE_ATTRS:
            if a in n and n[a] is not None:
                L.append(f"[{_fmt(nid)} {a} {_fmt(n[a])} {tx} :add]")

    for e in edges:
        eid = f"en.{e[':en/from']}.{e[':en/kind'].lstrip(':')}.{e[':en/to']}"
        for a in EDGE_ATTRS:
            if a in e and e[a] is not None:
                L.append(f"{'[' + _fmt(eid)} {a} {_fmt(e[a])} {tx} :add]")

    L.append(";; ── DERIVED readouts (transient; integral of incident 縁, computed on read) ──")
    for nid, v in sorted(res["openness"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/participation-openness {v:g} {tx} :derived] ;; :bond/is-transient true")
    for nid, v in sorted(res["enclosure"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/enclosure-load {v:g} {tx} :derived] ;; :bond/is-transient true")
    for nid, v in sorted(res["enclosure_out"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/enclosure-imposed {v:g} {tx} :derived] ;; :bond/is-transient true")

    L.append("]")
    return "\n".join(L) + "\n"

def authorize_posting(posting: dict, signature: dict) -> dict:
    """Post a staged entry. ONLY a member-origin signature authorizes (G4 no-server-key); a
    server signature is refused. Posting is append-only (G7) — the returned datom is final."""
    if posting.get("state") != "staged":
        return {**posting, "refused": True, "reason": "posting is not in :staged state"}
    if signature.get("origin") != "member":
        return {**posting, "refused": True,
                "reason": "only a member passkey/wallet signature posts to the ledger (G4 no-server-key)"}
    return {**posting, "state": "posted", "postedSig": signature.get("ref")}

def detect_single_bidder_streak(records: list[dict], params: dict) -> list[dict]:
    """Find (authority, awardee) pairs with ≥minConsecutive consecutive single-bid awards
    inside a rolling windowMonths. Returns hit dicts {authority, awardee, cids, count}.
    A FACT about the public record — single-bid procurement is lawful (see false positives)."""
    min_consec = int(params.get("minConsecutive", 5))
    window = int(params.get("windowMonths", 24))
    require_flag = bool(params.get("requireSingleBidFlag", True))

    by_pair: dict[tuple, list[dict]] = {}
    for r in records:
        key = (r.get("contractingAuthority"), r.get("awardeeLei"))
        by_pair.setdefault(key, []).append(r)

    hits: list[dict] = []
    for (auth, awardee), recs in by_pair.items():
        recs = sorted(recs, key=lambda x: x.get("awardDate", ""))
        run: list[dict] = []

        def _flush(run_recs: list[dict]) -> None:
            if len(run_recs) >= min_consec:
                if _months_between(run_recs[0]["awardDate"], run_recs[-1]["awardDate"]) <= window:
                    hits.append({"authority": auth, "awardee": awardee,
                                 "cids": [r["cid"] for r in run_recs], "count": len(run_recs)})

        for r in recs:
            is_single = (r.get("bidCount") == 1) and (r.get("singleBidFlag", False) if require_flag else True)
            if is_single:
                run.append(r)
            else:
                _flush(run)
                run = []
        _flush(run)
    return hits

