def _walk(node: Any, path: str = ""):
    if isinstance(node, dict):
        for k, v in node.items():
            yield path, "key", k
            yield from _walk(v, f"{path}/{k}")
    elif isinstance(node, (list, tuple)):
        for x in node:
            yield from _walk(x, path)
    else:
        yield path, "value", node

