        for d in tx.get(":tx/datoms", []):
            if len(d) < 4:
                continue
            _op, _e, a, v = d[0], d[1], d[2], d[3]
            if a == ":aburi-bridge/pushed-to-tx":
                pushed_to = v
            elif a == ":aburi-bridge/parent-commit":
                parent = v
    return {"pushed_to": pushed_to, "parent_commit": parent}

