            voter_did=r.get(":ballot/voter", r.get("voter", "?")),
            choice=_kw(r.get(":ballot/choice", r.get("choice", "yes"))),
            cast_at=int(r.get(":ballot/cast-at", r.get("cast_at", 0))),
        ))
    return out

