def mcp_call(url, name, arguments, rid=1, token=None):
    body = json.dumps({
        "jsonrpc": "2.0", "id": rid, "method": "tools/call",
        "params": {"name": name, "arguments": arguments},
    }).encode()
    req = urllib.request.Request(url + "/mcp", data=body,
