                return {"stance": min(1.0, max(0.0, v)), "via": ":murakumo"}
            except (ValueError, IndexError):
                pass
    nx = susceptibility * neighbour_mean + (1.0 - susceptibility) * anchor
    return {"stance": min(1.0, max(0.0, nx)), "via": ":kernel-fallback"}

