def project(state: dict[str, Any]) -> dict[str, Any]:
    cs = State(**state.get("cell_state", {}))
    for f in ("article_id", "source_actor", "source_tid", "men", "headline"):
        setattr(cs, f, state.get(f, getattr(cs, f)))
    cs.member_signed = bool(state.get("member_signed", cs.member_signed))
    cs.server_held_key = bool(state.get("server_held_key", cs.server_held_key))
    cs.speak_as = bool(state.get("speak_as", cs.speak_as))
    cs.mentions = list(state.get("mentions", cs.mentions))

    def refuse(msg: str) -> dict[str, Any]:
        cs.refusal, cs.phase = msg, Phase.REFUSED.value
        return {"cell_state": cs.__dict__}

    if not cs.source_actor or not cs.source_tid:
        return refuse("G11: an :actor-event needs source_actor + source_tid (provenance to the Datom)")
    if cs.server_held_key:
        return refuse("G7: server never signs a projection; member signature required (no-server-key)")
    if not cs.member_signed:
        return refuse("G7: projection not member-signed; refused (no-server-key)")
    if cs.speak_as:
        return refuse("G9: kawaraban observes the actor's event, never speaks AS the actor")

    cs.payload = {"articleId": cs.article_id, "kind": "actor-event", "men": cs.men,
                  "sourceActor": cs.source_actor, "sourceTid": cs.source_tid,
                  "headline": cs.headline, "serverHeldKey": False, "speakAs": False,
                  "wires": len(cs.mentions)}
    cs.refusal, cs.phase = "", Phase.PROJECTED.value
    return {"cell_state": cs.__dict__}

def compose(state: dict[str, Any]) -> dict[str, Any]:
    cs = State(**state.get("cell_state", {}))
    cs.issue_id = state.get("issue_id", cs.issue_id)
    cs.rank_signals = [_norm(s) for s in state.get("rank_signals", cs.rank_signals)]
    cs.lead_ids = list(state.get("lead_ids", cs.lead_ids))
    cs.final = bool(state.get("final", cs.final))
    cs.member_signed = bool(state.get("member_signed", cs.member_signed))
    cs.operator_gated = bool(state.get("operator_gated", cs.operator_gated))
    cs.server_held_key = bool(state.get("server_held_key", cs.server_held_key))

    def refuse(msg: str) -> dict[str, Any]:
        cs.refusal, cs.phase = msg, Phase.REFUSED.value
        return {"cell_state": cs.__dict__}

    for s in cs.rank_signals:
        if s not in ALLOWED_RANK:
            return refuse(f"G2: rank signal {s!r} not public-good; paid/engagement ranking unrepresentable")
    if cs.final:
        return refuse("G10: an edition is never final (非終末論)")
    if cs.server_held_key:
        return refuse("G7: server never signs an edition (no-server-key)")

    # G7/G8 — publication requires member signature AND operator gate; otherwise composed-but-unpublished.
    cs.published = bool(cs.member_signed and cs.operator_gated)
    cs.payload = {"issueId": cs.issue_id, "rankSignals": cs.rank_signals,
                  "leadCount": len(cs.lead_ids), "final": False, "serverHeldKey": False,
                  "published": cs.published}
    cs.refusal, cs.phase = "", Phase.COMPOSED.value
    return {"cell_state": cs.__dict__}

def ingest(state: dict[str, Any]) -> dict[str, Any]:
    cs = State(**state.get("cell_state", {}))
    cs.outlet_id = state.get("outlet_id", cs.outlet_id)
    cs.name = state.get("name", cs.name)
    cs.kind = _norm(state.get("kind", cs.kind))
    cs.access = _norm(state.get("access", cs.access))

    def refuse(msg: str) -> dict[str, Any]:
        cs.refusal, cs.phase = msg, Phase.REFUSED.value
        return {"cell_state": cs.__dict__}

    if not cs.outlet_id or not cs.name:
        return refuse("outlet needs id + name (G5 provenance)")
    if cs.access not in OPEN_ACCESS:
        return refuse(f"G4: access {cs.access!r} is not a public facing page; paywall/terminal not mirrored")
    if cs.kind not in OUTLET_KINDS:
        return refuse(f"unknown outlet kind {cs.kind!r}")

    cs.payload = {"outletId": cs.outlet_id, "name": cs.name, "kind": cs.kind,
                  "access": cs.access, "sourcing": "representative"}
    cs.refusal, cs.phase = "", Phase.INGESTED.value
    return {"cell_state": cs.__dict__}

