def transition_to_composed(state: dict[str, Any]) -> dict[str, Any]:
    cs = _state(state)
    cs.committees = state.get("committees", cs.committees)
    if not cs.committees:
        cs.refusal = "no committees to compose"
        cs.phase = CommitteePhase.REFUSED.value
        return {"cell_state": cs.__dict__}
    by_seat: dict[str, list] = {}
    for c in cs.committees:
        for seat in c.get("members", []):
            by_seat.setdefault(seat, []).append(c.get("id"))
    cs.co_membership = [
        {"seat": s, "committees": sorted(set(cl))}
        for s, cl in sorted(by_seat.items()) if len(set(cl)) > 1
    ]
    cs.phase = CommitteePhase.COMPOSED.value
    return {"cell_state": cs.__dict__}

def transition_to_aggregated(state: dict[str, Any]) -> dict[str, Any]:
    cs = _state(state)
    cs.money = state.get("money", cs.money)
    if not cs.money:
        cs.refusal = "no money flows to aggregate"
        cs.phase = MoneyPhase.REFUSED.value
        return {"cell_state": cs.__dict__}
    by_payee: dict[str, float] = {}
    for m in cs.money:
        by_payee[m.get("payee")] = by_payee.get(m.get("payee"), 0.0) + float(m.get("amount", 0.0))
    cs.total = sum(by_payee.values())
    shares = {p: (v / cs.total if cs.total else 0.0) for p, v in by_payee.items()}
    cs.hhi = round(sum(s * s for s in shares.values()), 4)
    cs.shares = sorted(([p, round(s, 4)] for p, s in shares.items()), key=lambda x: -x[1])
    cs.phase = MoneyPhase.AGGREGATED.value
    return {"cell_state": cs.__dict__}

def transition_to_woven(state: dict[str, Any]) -> dict[str, Any]:
    cs = _state(state)
    cs.nodes = state.get("nodes", cs.nodes)
    cs.committees = state.get("committees", cs.committees)
    if not cs.committees:
        cs.refusal = "no committees to weave"
        cs.phase = WeavePhase.REFUSED.value
        return {"cell_state": cs.__dict__}
    for c in cs.committees:
        organs = sorted({cs.nodes.get(m, {}).get("organ", "(unknown)") for m in c.get("members", [])})
        cs.findings.append({
            "committee": c.get("id"),
            "member_count": len(c.get("members", [])),
            "distinct_organs": len(organs),
            "organs": organs,
        })
    cs.phase = WeavePhase.WOVEN.value
    return {"cell_state": cs.__dict__}

