def handle_geothermal_micro(state: dict) -> dict:
    """Thermal gradient assessment → geothermal potential."""
    parcel_did = state.get("parcel_did", "")
    depth_m = state.get("depth_m", 0)

    if depth_m > 500:
        return {**state, "error": "depth > 500 m (infeasible)"}

    if not parcel_did:
        return {**state, "error": "parcel_did required"}

    geo_kw = 3 if depth_m >= 200 else 1 if depth_m >= 100 else 0
    return {
        **state,
        "geo_potential_kw": geo_kw,
        "feasible": geo_kw > 0,
        "generation_record_id": f"gen.geo.{parcel_did.split('/')[-1]}",
    }

def _top_level_entities(s: str):
    """Yield each top-level {...} map literal inside the outer [ ... ] vector."""
    s = _strip_comments(s)
    start = s.find("[")
    if start < 0:
        return
    depth = 0
    buf = []
    in_str = False
    for c in s[start + 1:]:
        if in_str:
            buf.append(c)
            if c == '"':
                in_str = False
            continue
        if c == '"':
            in_str = True
            buf.append(c)
            continue
        if c == "{":
            depth += 1
            buf.append(c)
        elif c == "}":
            depth -= 1
            buf.append(c)
            if depth == 0:
                yield "".join(buf).strip()
                buf = []
        elif depth > 0:
            buf.append(c)

def _read_value(tok: str):
    tok = tok.strip()
    if tok.startswith('"') and tok.endswith('"'):
        return json.loads(tok)  # JSON string decode handles escapes
    if tok.startswith("["):
        inner = tok[1:-1]
        return [_read_value(t.group(0)) for t in _TOKEN_RE.finditer(inner)]
    if tok.startswith(":"):
        return tok[1:]  # keyword → bare name (stored as a string claim)
    # numeric?
    try:
        return int(tok)
    except ValueError:
        try:
            return float(tok)
        except ValueError:
            return tok

