def verify_signature(envelope: dict, signature: dict) -> tuple[bool, list[str]]:
    """Structurally verify a com.etzhayyim.esign.signature against its envelope.

    Checks the bindings hinagata CAN check without a key: signer is on the roster, the document
    hash the signer attested matches the envelope (anti-tamper), and the WebAuthn algorithm is
    an accepted one. The CRYPTOGRAPHIC assertion verification (WebAuthn / DID-key) is done by
    kotoba-auth, not here — this is the structural gate that precedes it."""
    reasons = []
    if signature.get("signerDid") not in envelope.get("signers", []):
        reasons.append("signerDid not in envelope.signers roster")
    if signature.get("documentSha256") != envelope.get("documentSha256"):
        reasons.append("documentSha256 mismatch (document tampered between request and sign)")
    if signature.get("webauthnAlgorithm") not in ("ES256", "EdDSA"):
        reasons.append(f"unsupported webauthn algorithm: {signature.get('webauthnAlgorithm')}")
    if not signature.get("assertionEnvelope"):
        reasons.append("missing assertionEnvelope (encrypted WebAuthn assertion)")
    return (len(reasons) == 0, reasons)

