def _parse_entity(block: str) -> dict:
    """Parse one `{:ns/attr value ...}` map into {attr-keyword: python-value}."""
    inner = block.strip()
    if inner.startswith("{"):
        inner = inner[1:]
    if inner.endswith("}"):
        inner = inner[:-1]
    toks = [m.group(0) for m in _TOKEN_RE.finditer(inner)]
    out: dict = {}
    i = 0
    while i < len(toks):
        key = toks[i]
        if not key.startswith(":"):
            i += 1
            continue
        if i + 1 >= len(toks):
            break
        out[key[1:]] = _read_value(toks[i + 1])
        i += 2
    return out

