def commons_pool(txs: list[dict]) -> dict:
    """The standing commons pool (single pass, fleet-scale safe). Returns
    {offered, drawn, available} in nutrient units. offered = Σ commons metabolite nutrient;
    drawn = Σ :symbiosis/draw amount; available = offered − drawn (≥0)."""
    meta: dict[str, dict] = {}
    drawn = 0
    for tx in txs:
        for _op, e, a, v in tx.get(":tx/datoms", []):
            if a == ":metabolite/kind":
                meta.setdefault(e, {})["kind"] = v
            elif a == ":metabolite/commons":
                meta.setdefault(e, {})["commons"] = v
            elif a == ":metabolite/nutrient":
                meta.setdefault(e, {})["nutrient"] = v
            elif a == ":symbiosis/amount":
                drawn += v
    offered = sum(m.get("nutrient", 0) for m in meta.values()
                  if m.get("kind") == ":refined" and m.get("commons") is True)
    return {"offered": offered, "drawn": drawn, "available": max(0, offered - drawn)}

def did_key_from_pubkey(pub: bytes) -> str:
    """Raw 32-byte Ed25519 pubkey → did:key:z6Mk… (multicodec 0xed01 + base58btc)."""
    return "did:key:z" + _b58(bytes([0xed, 0x01]) + pub)

def graph_cid(name: str) -> str:
    """KotobaCid::from_bytes(name) — CIDv1 dag-cbor sha2-256, base32lower. Matches the engine."""
    raw = bytes([0x01, 0x71, 0x12, 0x20]) + hashlib.sha256(name.encode("utf-8")).digest()
    return "b" + base64.b32encode(raw).decode("ascii").rstrip("=").lower()

def _strip_comments(s: str) -> str:
    out = []
    in_str = False
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if in_str:
            out.append(c)
            if c == '"' and s[i - 1] != "\\":
                in_str = False
            i += 1
            continue
        if c == '"':
            in_str = True
            out.append(c)
            i += 1
            continue
        if c == ";":
            while i < n and s[i] != "\n":
                i += 1
            continue
        out.append(c)
        i += 1
    return "".join(out)

def _top_level_entities(s: str):
    """Yield each top-level {...} map literal inside the outer [ ... ] vector."""
    s = _strip_comments(s)
    start = s.find("[")
    if start < 0:
        return
    depth = 0
    buf = []
    in_str = False
    for c in s[start + 1:]:
        if in_str:
            buf.append(c)
            if c == '"':
                in_str = False
            continue
        if c == '"':
            in_str = True
            buf.append(c)
            continue
        if c == "{":
            depth += 1
            buf.append(c)
        elif c == "}":
            depth -= 1
            buf.append(c)
            if depth == 0:
                yield "".join(buf).strip()
                buf = []
        elif depth > 0:
            buf.append(c)

