def _atom(t: str):
    if t.startswith('"'):
        return t[1:-1].replace('\\"', '"').replace('\\\\', '\\')
    if t == 'true':  return True
    if t == 'false': return False
    if t == 'nil':   return None
    if t.startswith(':'):
        return t  # keep keywords as ":ns/name" strings
    try:
        return int(t)
    except ValueError:
        try:
            return float(t)
        except ValueError:
            return t

def _fmt(v) -> str:
    if v is True:
        return "true"
    if v is False:
        return "false"
    if v is None:
        return "nil"
    if isinstance(v, str):
        return v if v.startswith(":") else '"' + v.replace('\\', '\\\\').replace('"', '\\"') + '"'
    if isinstance(v, float):
        return f"{v:g}"
    return str(v)

def emit(nodes: dict, edges: list, res: dict, tx: int = 1) -> str:
    L = []
    L.append(";; inochi 命 — GENERATED kotoba Datom log (ADR-2606073000). DO NOT hand-edit.")
    L.append(";; Canonical EAVT state (ADR-2605312345). [e a v tx op].")
    L.append(";; GROUND op :add = durable. DERIVED :bond/is-transient = computed on read (N1/G2).")
    L.append("[")

    # ── GROUND: node datoms
    for nid in nodes:  # insertion order (EDN read order) → deterministic
        n = nodes[nid]
        for a in NODE_ATTRS:
            if a in n and n[a] is not None:
                L.append(f"[{_fmt(nid)} {a} {_fmt(n[a])} {tx} :add]")

    # ── GROUND: edge datoms (edge entity id is content-stable: en.<from>.<kind>.<to>)
    for e in edges:
        eid = f"en.{e[':en/from']}.{e[':en/kind'].lstrip(':')}.{e[':en/to']}"
        for a in EDGE_ATTRS:
            if a in e and e[a] is not None:
                L.append(f"{'[' + _fmt(eid)} {a} {_fmt(e[a])} {tx} :add]")

    # ── DERIVED (transient — NOT persisted; N1/G2)
    L.append(";; ── DERIVED readouts (transient; integral of incident 縁, computed on read) ──")
    for nid, v in sorted(res["restoration"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/restoration-priority {v:g} {tx} :derived] ;; :bond/is-transient true")
    for nid, v in sorted(res["fragility"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/dependency-fragility {v:g} {tx} :derived] ;; :bond/is-transient true")
    for nid, v in sorted(res["pressure_out"].items(), key=lambda kv: -kv[1]):
        L.append(f"[{_fmt(nid)} :bond/pressure-imposed {v:g} {tx} :derived] ;; :bond/is-transient true")

    L.append("]")
    return "\n".join(L) + "\n"

