def assign_vehicle_node(state: DispatchState) -> dict:
    """G15: pick the smallest available vehicle whose capacity covers the load."""
    if datalog is None:
        return {"vehicle": ""}
    vehs = datalog.q(
        "[:find ?id ?cap :in $ ?j :where [?v :vehicle/jurisdiction ?j] "
        "[?v :vehicle/status :available] [?v :vehicle/id ?id] [?v :vehicle/capacity-kg ?cap]]",
        state["jurisdiction"],
    )
    feasible = sorted([(c, vid) for vid, c in vehs if c >= state["load_kg"]])
    return {"vehicle": feasible[0][1] if feasible else ""}

def _post(url: str, body: dict, token: str | None = None) -> tuple[int, dict]:
    data = json.dumps(body).encode("utf-8")
    req = urllib.request.Request(url, data=data, method="POST")
    req.add_header("Content-Type", "application/json")
    if token:
        req.add_header("Authorization", f"Bearer {token}")
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.status, json.loads(resp.read().decode("utf-8") or "{}")
    except urllib.error.HTTPError as e:
        try:
            payload = json.loads(e.read().decode("utf-8") or "{}")
        except Exception:
            payload = {"error": str(e)}
        return e.code, payload

def conflicting_clauses(nodes, edges, clause):
    out = set()
    for e in edges:
        if e.get(":en/kind") == ":conflicts-with":
            if e[":en/from"] == clause:
                out.add(e[":en/to"])
            elif e[":en/to"] == clause:
                out.add(e[":en/from"])
    return sorted(out)

def jurisdictions_for_concept(nodes, edges, concept):
    # clauses that instantiate the concept → statutes they cite → those statutes' jurisdictions
    clauses = {e[":en/from"] for e in edges if e.get(":en/kind") == ":instantiates" and e[":en/to"] == concept}
    jx = set()
    for e in edges:
        if e.get(":en/kind") in CITE_KINDS and e[":en/from"] in clauses:
            j = nodes.get(e[":en/to"], {}).get(":statute/jurisdiction")
            if j:
                jx.add(j)
    return sorted(jx)

def calc_recovery_rate(ferrous_kg: float, non_ferrous_kg: float, copper_kg: float,
                       asr_kg: float, input_mass_kg: float) -> dict:
    """G13 Material recovery ≥95%; ASR <5% to landfill."""
    total_recovered = ferrous_kg + non_ferrous_kg + copper_kg
    recovery_pct = (total_recovered / input_mass_kg * 100) if input_mass_kg > 0 else 0
    asr_pct = (asr_kg / input_mass_kg * 100) if input_mass_kg > 0 else 0

    if recovery_pct < 95.0:
        return {"ok": False, "reason": f"Recovery {recovery_pct}% < 95% (G13)", "blocked": True}
    if asr_pct >= 5.0:
        return {"ok": False, "reason": f"ASR landfill {asr_pct}% >= 5% (G13)", "blocked": True}
    return {
        "ok": True,
        "reason": f"Recovery {recovery_pct}% ≥ 95%, ASR {asr_pct}% < 5% (G13)",
        "recovery_pct": int(recovery_pct),
        "asr_landfill_pct": int(asr_pct)
    }

