def suppression(stats: dict[str, dict], *, now_beat: int) -> dict[str, int]:
    """rule → suppressed-until-beat for every rule whose consecutive rejections reached the
    threshold. This is the colony declining to repeat what its humans keep declining."""
    return {rule: now_beat + SUPPRESS_BEATS
            for rule, s in stats.items()
            if s["consecutive_rejected"] >= SUPPRESS_AFTER}

def should_emit(rule: str, suppress_table: dict[str, int], beat: int) -> bool:
    """Observer-side gate: may this rule emit a proposal at this beat?"""
    return beat >= suppress_table.get(rule, -1)

def write_outcomes(outcomes: list[dict], path: pathlib.Path) -> int:
    """Write the outcomes NDJSON kaizen_feedback.read_outcomes consumes (overwrite — the
    file is a SNAPSHOT of current PR states; the as-of history lives on the Datom log via
    kaizen_feedback.feedback_datoms, not in this file)."""
    p = pathlib.Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text("".join(json.dumps(o, ensure_ascii=False, sort_keys=True) + "\n"
                         for o in outcomes), encoding="utf-8")
    return len(outcomes)

def _default_transport(url: str, body: dict, timeout_s: float = 60.0,
                       operator_auth: bool = True) -> dict:
    """POST a transact. When `operator_auth` (the loopback fallback) → attach the unsigned
    operator bearer. When NOT (the delegated path) → send NO Authorization header: auth is the
    member-signed `cacao_b64` already in the body, and the actor is the principal, not the
    operator."""
    assert_kotoba(url)
    headers = {"Content-Type": "application/json"}
    if operator_auth:
        headers["Authorization"] = f"Bearer {operator_bearer()}"
    req = urllib.request.Request(url, data=json.dumps(body).encode("utf-8"), headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=timeout_s) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        # surface the server's reason (e.g. a CACAO-verification message on the delegated
        # path) so a delegation issuer can see WHY a capability was rejected
        raise RuntimeError(f"kotoba transact HTTP {e.code}: {e.read().decode()[:200]}") from None

def events_for_beat(beat: int, *, actor: str = "", prev_followers: int | None = None,
                    live: bool | None = None, fetch=None) -> tuple[list[str], dict | None]:
    """The membrane's single entry point: (events, snapshot|None) for one organism-beat.

    snapshot is None on every offline/representative beat — offline logs carry no
    perception datoms, so R1 head CIDs are unchanged. Live failures fall back to the
    representative pattern (fail-open)."""
    is_live = (os.environ.get(LIVE_ENV) == "1") if live is None else live
    if not is_live or not actor:
        return representative_events(beat), None
    try:
        obs = LivePerception(fetch=fetch).observe(actor, prev_followers)
        return obs["events"], {"followers": obs["followers"]}
    except PerceptionBoundaryViolation:
        raise   # a boundary violation is a bug, never silently absorbed
    except Exception:
        return representative_events(beat), None

def siwe_message(p: dict) -> str:
    """Reconstruct the EIP-4361 plaintext kotoba_auth::Cacao::siwe_message() signs/verifies.
    did:key issuer ⇒ address = last colon segment, Chain ID = 1 (CAIP-122 default)."""
    addr = p["iss"].split(":")[-1]
    lines = [f"{p['domain']} wants you to sign in with your Ethereum account:", addr, ""]
    if p.get("statement"):
        lines += [p["statement"], ""]
    lines += [f"URI: {p['aud']}", f"Version: {p['version']}", "Chain ID: 1",
              f"Nonce: {p['nonce']}", f"Issued At: {p['iat']}"]
    if p.get("exp"):
        lines.append(f"Expiration Time: {p['exp']}")
    if p.get("resources"):
        lines.append("Resources:")
        lines += [f"- {r}" for r in p["resources"]]
    return "\n".join(lines)

def _cbor_str(s: str) -> bytes:
    b = s.encode("utf-8")
    n = len(b)
    if n < 24:
        head = bytes([0x60 | n])
    elif n < 256:
        head = bytes([0x78, n])
    else:
        head = bytes([0x79, n >> 8, n & 0xFF])
    return head + b

def check_sla_compliance(request_date_iso: str, sla_date_iso: str) -> dict:
    """Verify activation request can meet legal SLA date without artificial delay."""
    if not request_date_iso or not sla_date_iso:
        return {"ok": False, "reason": "request or SLA date missing (G5)"}
    # R0 stub: just check date strings exist; full ISO-8601 parse deferred to Phase 1+
    if "T" not in request_date_iso or "T" not in sla_date_iso:
        return {"ok": False, "reason": "invalid ISO-8601 date format (G5)"}
    return {"ok": True, "reason": "SLA compliance window OK"}

