def collect_rdns(ip_text: str):
    """Reverse-DNS PTR for one IP (live; socket only). Returns an :rdns/* dict or None."""
    import socket
    try:
        host, _aliases, _addrs = socket.gethostbyaddr(ip_text)
    except (socket.herror, socket.gaierror, OSError):
        return None
    verified = False
    try:
        fwd = {ai[4][0] for ai in socket.getaddrinfo(host, None)}
        verified = ip_text in fwd
    except (socket.gaierror, OSError):
        pass
    return {":rdns/id": f"rdns.{_slug(ip_text)}", ":rdns/ip": f"ip.{('v6.' if ':' in ip_text else 'v4.')}{_slug(ip_text)}",
            ":rdns/ptr": host, ":rdns/verified": verified, ":rdns/sourcing": ":authoritative"}

def _parse(it):
    t = next(it)
    if t == '[':
        out = []
        while (x := _parse(it)) is not _END:
            out.append(x)
        return out
    if t == '{':
        out = {}
        while (k := _parse(it)) is not _END:
            v = _parse(it)
            out[k] = v
        return out
    if t in (']', '}'):
        return _END
    return _atom(t)

def load_edn(path: pathlib.Path):
    it = _tokens(pathlib.Path(path).read_text(encoding='utf-8'))
    return _parse(it)

def _add(entity: str, attr: str, value: Any) -> list:
    """One append-only EAVT assertion: [:db/add <entity> <attr> <value>]."""
    return [":db/add", entity, attr, value]

def rows_to_datoms(rows):
    """Each entity map → [:db/add E A V] strings (E = its id; lists fan out)."""
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        e = next((r[k] for k in ID_KEYS if k in r), None)
        if e is None:
            continue
        for k, v in r.items():
            if k in ID_KEYS:
                continue
            for item in (v if isinstance(v, list) else [v]):
                out.append(f"[:db/add {edn_str(e)} {k} {edn_val(item)}]")
    return out

