                              "unit": r[3] if len(r) > 3 else ""}
    for r in _opt("tokutei.csv"):
        raw["tokutei"][r[0]] = {"name": r[1], "yakka": float(r[2]),
                                "unit": r[3] if len(r) > 3 else ""}
    for r in _opt("shobyo.csv"):
