def yakka_to_ten(price_yen: float) -> int:
    """薬価(円)→ 点数. ≤15円→1点; >15円→ price/10 を五捨五超四入."""
    if price_yen <= 15:
        return 1
    q = price_yen / 10.0
    floor = math.floor(q)
    frac = q - floor
    # 五捨五超: 0.5ちょうど以下は切捨, 0.5超は切上
    return int(floor if frac <= 0.5 + 1e-9 else floor + 1)

def round_ichibu_futan(yen: float) -> int:
    """一部負担金 端数処理: 10円未満四捨五入 (5円以上切上)."""
    return int((int(round(yen)) + 5) // 10 * 10)

def _severity(value: float, spec: dict) -> str | None:
    """Return 'critical' | 'warn' | None for a value against a (warn, critical) threshold."""
    if value is None or value == float("inf"):
        return None
    if spec["polarity"]:  # higher-better → alert when below
        if value < spec["critical"]:
            return "critical"
        if value < spec["warn"]:
            return "warn"
    else:                 # lower-better → alert when above
        if value > spec["critical"]:
            return "critical"
        if value > spec["warn"]:
            return "warn"
    return None

def evaluate(stations: dict, res: dict, thresholds: dict | None = None) -> list:
    """Compare each scope's KPIs to thresholds → graded alert list (worst-first)."""
    th = thresholds or DEFAULT_THRESHOLDS
    scopes = [(":line.sarutahiko-a", res["_line"])]
    scopes += [(s, res[s]) for s in res if not s.startswith("_")]

    alerts = []
    for scope, kpis in scopes:
        for kpi, spec in th.items():
            if kpi not in kpis:
                continue
            sev = _severity(kpis[kpi], spec)
            if sev:
                alerts.append({
                    "scope": scope, "kpi": kpi, "value": kpis[kpi],
                    "threshold": spec["critical"] if sev == "critical" else spec["warn"],
                    "severity": sev,
                    "label": stations.get(scope, {}).get(":station/label", scope),
                })
    order = {"critical": 0, "warn": 1}
    return sorted(alerts, key=lambda a: (order[a["severity"]], a["scope"], a["kpi"]))

def _tokens(s: str):
    for m in _TOK.finditer(s):
        t = m.group(1)
        if t is not None:
            yield t

def _atom(t: str):
    if t.startswith('"'):
        return t[1:-1].replace('\\"', '"').replace('\\\\', '\\')
    if t == 'true':  return True
    if t == 'false': return False
    if t == 'nil':   return None
    if t.startswith(':'):
        return t
    try:
        return int(t)
    except ValueError:
        try:
            return float(t)
        except ValueError:
            return t

def _fmt(v) -> str:
    if v is True:
        return "true"
    if v is False:
        return "false"
    if v is None:
        return "nil"
    if v == float("inf"):
        return ":inf"
    if isinstance(v, str):
        return v if v.startswith(":") else '"' + v.replace('\\', '\\\\').replace('"', '\\"') + '"'
    if isinstance(v, float):
        return f"{v:g}"
    return str(v)

def split_lines(stations: dict, ticks: list) -> dict:
    """Group (stations, ticks) into {line_id: (line_stations, line_ticks)}."""
    by_line_st = defaultdict(dict)
    for sid, st in stations.items():
        by_line_st[st.get(":station/line", ":line.unknown")][sid] = st
    out = {}
    for line, lst in by_line_st.items():
        lt = [tk for tk in ticks if tk.get(":tick/station") in lst]
        out[line] = (lst, lt)
    return out

def parse_scan_datoms(text: str) -> list:
