    for f in forms:
        if isinstance(f, list) and len(f) == 5 and isinstance(f[1], str) and f[1].startswith(":scan/"):
            datoms.append(f)
    return datoms

def _guard_no_person(datoms: list) -> None:
    for e, a, v, tx, op in datoms:
