def screen_licenses(procs):
    """G1 enforcement point #3: refuse any process whose source-license is not
    practiceable-open. Raises ValueError so the analyzer cannot silently render a
    graph that includes a proprietary recipe (which would void the 'commons' claim)."""
    for pid, p in procs.items():
        lic = p.get(':iiiv.proc/source-license')
        if lic not in ALLOWED_LICENSES:
            raise ValueError(
                f"G1 violation: process {pid!r} has :source-license {lic!r}; only "
                f"{ALLOWED_LICENSES} are permitted (hotaru is an OPEN-PUBLICATION commons; "
                f"vendor-proprietary / patent-active / trade-secret recipes are excluded "
                f"by construction, per ADR-2605265500 §2)."
            )

def screen_fabrication(crystals, wafers):
    """G2 enforcement point #3: refuse any crystal/wafer marked fabricated. Raises
    ValueError — the model is design/spec ONLY through R3; physical fabrication is
    unrepresentable until the ADR-2605265500 R4+ gate (Council Lv7+)."""
    for cid, c in crystals.items():
        if c.get(':iiiv.crystal/fabricated') is not False:
            raise ValueError(
                f"G2 violation: crystal {cid!r} has :fabricated "
                f"{c.get(':iiiv.crystal/fabricated')!r}; only false is permitted "
                f"(III-V fabrication PROHIBITED through R3, ADR-2605265500 §2)."
            )
    for wid, w in wafers.items():
        if w.get(':iiiv.wafer/fabricated') is not False:
            raise ValueError(
                f"G2 violation: wafer {wid!r} has :fabricated "
                f"{w.get(':iiiv.wafer/fabricated')!r}; only false is permitted."
            )

def _post_json(url: str, token: str, path: str, payload: dict[str, object]) -> dict[str, object]:
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(
        url.rstrip("/") + path,
        data=body,
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"{path} failed: HTTP {exc.code}: {detail}") from exc

def read_log(log_path: pathlib.Path = LOG_DEFAULT) -> list[dict]:
    """Read the log back as a list of transaction dicts (uses the shared _edn reader)."""
    from _edn import _parse, _tokens
    if not log_path.exists():
        return []
    txs = []
    for line in log_path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        txs.append(_parse(_tokens(line)))
    return txs

def verify_chain(log_path: pathlib.Path = LOG_DEFAULT) -> dict:
    """Recompute every CID from its datoms + prev and verify the DAG is intact (no tampering).
    Returns {ok, length, broken_at}. The integrity proof of the append-only log."""
    txs = read_log(log_path)
    prev = ""
    for i, tx in enumerate(txs):
        expect = tx_cid(tx.get(":tx/datoms", []), prev)
        if tx.get(":tx/cid") != expect or tx.get(":tx/prev") != prev:
            return {"ok": False, "length": len(txs), "broken_at": i}
        prev = tx[":tx/cid"]
    return {"ok": True, "length": len(txs), "broken_at": -1}

def mood_events(outcomes: list[dict]) -> list[str]:
    """Map PR outcomes to joucho events — acceptance calms, rejection stresses (and
    sharpens focus). Pending moves nothing."""
    out = []
    for o in outcomes:
        if o["outcome"] == "merged":
            out.append(":event/kaizen-merged")
        elif o["outcome"] == "rejected":
            out.append(":event/kaizen-rejected")
    return out

def bridge_state(txs: list[dict]) -> dict:
    """Replay the durable push cursor from the local log: the LAST `:bridge/*` checkpoint
    wins. Returns {pushed_to, parent_commit}."""
    pushed_to, parent = 0, ""
    for tx in txs:
        for _op, _e, a, v in tx.get(":tx/datoms", []):
            if a == ":bridge/pushed-to-tx":
                pushed_to = v
            elif a == ":bridge/parent-commit":
                parent = v
    return {"pushed_to": pushed_to, "parent_commit": parent}

def write_receipts(receipts: list[dict], path: pathlib.Path) -> int:
    """Append receipts as NDJSON (receipts.py folds them onto the Datom log). Each line is
    rebuilt from the RECEIPT_FILE_KEYS whitelist — credentials are unrepresentable in this
    file by construction."""
    p = pathlib.Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    with p.open("a", encoding="utf-8") as fh:
        for r in receipts:
