def classify(rows):
    """Return dict bucket-name → (dict keyed by id for entities, list for edges)."""
    out = {name: {} for _k, name in _BUCKETS}
    keyed = {"rirs", "asns", "ranges", "ips"}
    for name in out:
        if name not in keyed:
            out[name] = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        for key, name in _BUCKETS:
            if key in r:
                if name in keyed:
                    out[name][r[key]] = r
                else:
                    out[name].append(r)
                break
    return out

