def futan_kubun(num_kohi: int, hoken: bool = True) -> str:
    """保険・公費の組合せ → 負担区分コード (代表的な単純ケース).

      保険単独            → "1"
      保険 + 第1公費      → "2"
      保険 + 第1 + 第2公費 → "3"
      第1公費単独         → "5"
    """
    if hoken and num_kohi == 0:
        return "1"
    if hoken and num_kohi == 1:
        return "2"
    if hoken and num_kohi >= 2:
        return "3"
    if not hoken and num_kohi >= 1:
        return "5"
    return "1"

