def reconcile(detections: list, res: dict | None = None) -> dict:
    """Reduce manako detections to a per-station defect-class Pareto + scan-cycle cross-check."""
    by_station = defaultdict(lambda: dict(inspected=0, defect_classes=defaultdict(int),
                                          scrap=0, rework=0, passed=0))
    for d in detections:
        st = d.get(":detect/station")
        a = by_station[st]
        a["inspected"] += 1
        v = d.get(":detect/verdict")
        if v == SCRAP:
            a["scrap"] += 1
        elif v == REWORK:
            a["rework"] += 1
        elif v == PASS:
            a["passed"] += 1
        cls = d.get(":detect/class")
        if cls and cls != NON_DEFECT_CLASS:
            a["defect_classes"][cls] += 1

    out = {}
    for st, a in by_station.items():
        pareto = sorted(a["defect_classes"].items(), key=lambda kv: (-kv[1], kv[0]))
        rec = dict(
            inspected=a["inspected"], scrap=a["scrap"], rework=a["rework"], passed=a["passed"],
            defect_pareto=pareto,
            top_defect=(pareto[0][0] if pareto else None),
        )
        if res is not None and st in res:
            # cross-check: does the detector's scrap count agree with the scan-cycle scrap count?
            rec["scancycle_scrap"] = res[st]["scrap"]
            rec["scrap_agrees"] = (a["scrap"] == res[st]["scrap"])
        out[st] = rec
    return out

def bottleneck_relief(res: dict) -> dict:
    """Lifting the worst station to the 2nd-worst raises the whole serial line's OEE."""
    sids = _stations(res)
    if len(sids) < 2:
        return {"current_line_oee": res["_line"]["oee"], "target_line_oee": res["_line"]["oee"],
                "oee_uplift_frac": 0.0, "bottleneck": None, "lifts_to": None}
    by_oee = sorted(sids, key=lambda s: res[s]["oee"])
    worst, second = by_oee[0], by_oee[1]
    cur = res[worst]["oee"]
    target = res[second]["oee"]  # new line OEE once the single bottleneck is relieved
    return {
        "current_line_oee": cur,
        "target_line_oee": target,
        "oee_uplift_frac": ((target - cur) / cur if cur > 0 else 0.0),
        "bottleneck": worst,
        "lifts_to": second,
        # relief is availability/performance recovery, never sub-takt speed-up (G2)
        "relief_levers": ["availability (remove unplanned stops)",
                          "performance (reduce minor stops / idle), within takt"],
    }

def _slope(xs: list, ys: list) -> float:
    n = len(xs)
    if n < 2:
        return 0.0
    mx = sum(xs) / n
    my = sum(ys) / n
    den = sum((x - mx) ** 2 for x in xs)
    if den == 0:
        return 0.0
    return sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / den

