def _edn_scalar(v):
    """Encode a Python value as an EDN scalar string for a kotoba Datom `v_edn`.

    Mirrors the `[{e,a,v_edn}]` contract that `KotobaNode.loadDatoms` ingests:
      str starting with ':' → bare EDN keyword (`:semiconductors`)
      other str            → EDN string literal (`"TSMC"`)
      int/float            → bare number
    Returns None for values that should not produce a Datom (None / "").
    """
    if v is None:
        return None
    if isinstance(v, bool):  # guard: bool is an int subclass
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return repr(v)
    s = str(v)
    if s == "":
        return None
    if s.startswith(":"):
        return s  # already an EDN keyword
    return json.dumps(s, ensure_ascii=False)  # EDN string literal

def _tokens(s: str):
    for m in _TOK.finditer(s):
        t = m.group(1)
        if t is not None:
            yield t

def _atom(t: str):
    if t.startswith('"'):
        return t[1:-1].replace('\\"', '"').replace('\\\\', '\\')
    if t == 'true':  return True
    if t == 'false': return False
    if t == 'nil':   return None
    if t.startswith(':'):
        return t
    try:
        return int(t)
    except ValueError:
        try:
            return float(t)
        except ValueError:
            return t

def cidv1_raw(data: bytes) -> str:
    """CIDv1 / raw (0x55) / sha2-256 — matches `ipfs add --cid-version=1 --raw-leaves`."""
    mh = bytes([0x12, 0x20]) + hashlib.sha256(data).digest()  # sha2-256, 32-byte digest
    cid = bytes([0x01, 0x55]) + mh                            # CIDv1, raw codec
    return "b" + _base32(cid)

def sha256_hex(data: bytes) -> str:
    """0x-prefixed lowercase hex SHA-256 — the esign documentSha256 defense-in-depth hash."""
    return "0x" + hashlib.sha256(data).hexdigest()

def _fmt(v) -> str:
    if v is True:
        return "true"
    if v is False:
        return "false"
    if v is None:
        return "nil"
    if isinstance(v, str):
        return v if v.startswith(":") else '"' + v.replace('\\', '\\\\').replace('"', '\\"') + '"'
    if isinstance(v, float):
        return f"{v:g}"
    return str(v)

