def regressions(trends: dict) -> list:
    """Flat list of (scope, kpi, rel_change) for every degrading series — the attention list."""
    rows = []
    for scope, kpis in trends.items():
        for attr, t in kpis.items():
            if t["regression"]:
                rows.append((scope, attr, t["rel_change"]))
    return sorted(rows, key=lambda r: -abs(r[2]))

def classify(rows):
    """Return (companies, addresses, contacts, edges, processes) keyed/listed."""
    companies, addresses, contacts, edges, processes = {}, [], [], [], []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if ':company/id' in r:
            companies[r[':company/id']] = r
        elif ':company.address/id' in r:
            addresses.append(r)
        elif ':company.contact/id' in r:
            contacts.append(r)
        elif ':supply.edge/id' in r:
            edges.append(r)
        elif ':company.process/id' in r:
            processes.append(r)
    return companies, addresses, contacts, edges, processes

def edn_str(s: str) -> str:
    """EDN-escape a python string into a quoted EDN string literal."""
